class Solution {
  public int[] bestCoordinate(int[][] towers, int radius) {
    int[] best = {0, 0};
    double bestQuality = -1;
    for (int x = 0; x <= 50; x++)
      for (int y = 0; y <= 50; y++) {
        double quality = 0;
        for (int[] tower : towers) {
          double distance = Math.hypot(x - tower[0], y - tower[1]);
          if (distance <= radius) quality += tower[2] / (1 + distance);
        }
        if (quality > bestQuality + 1e-9) {
          bestQuality = quality;
          best[0] = x;
          best[1] = y;
        }
      }
    return best;
  }
}
